let state={version:2,projects:[],memories:[],events:[],stars:[],history:[]};
let revision=0,syncState='loading',lastSync='',openProjectId=null,writeBusy=false,pollTimer=0;
function updateSave(){const e=$('#save-status');e.textContent=syncState==='loading'?'Caricamento dell’archivio privato…':syncState==='saving'?'Salvataggio sul server…':syncState==='error'?'Connessione interrotta · riprova prima di modificare':'Archivio privato sincronizzato · '+lastSync;const b=$('#syncStatus');if(b){b.textContent=syncState==='error'?'Riconnetti':syncState==='loading'?'Caricamento…':syncState==='saving'?'Salvataggio…':'Sincronizzato';b.classList.toggle('sync-error',syncState==='error');}}
function applyServer(v){if(!v?.state||v.revision<revision)return;state=v.state;revision=v.revision;syncState='ready';lastSync=new Date(v.updatedAt).toLocaleTimeString('it-IT',{timeZone:'Europe/Rome',hour:'2-digit',minute:'2-digit'});render();if(openProjectId&&$('#modal').open)showProject(openProjectId);}
async function reloadState(){if(writeBusy)return;try{applyServer(await ClaraTransport.load());}catch(e){syncState='error';updateSave();if(!revision&&view!=='scrivania')$('#main').innerHTML=info('Non riesco a leggere l’archivio. Apri Clara con il tuo account ChatGPT e premi Riconnetti.');}finally{schedulePoll();}}
function schedulePoll(){clearTimeout(pollTimer);pollTimer=setTimeout(()=>{if(!document.hidden)reloadState();else schedulePoll();},state.projects.some(p=>p.status==='lavorazione')?2200:12000);}
async function dispatch(payload,message){if(writeBusy){notify('Un salvataggio è già in corso.');return null;}if(syncState!=='ready'){notify('Attendi la sincronizzazione oppure premi Riconnetti.');return null;}writeBusy=true;syncState='saving';updateSave();document.body.classList.add('saving');try{const value=await ClaraTransport.command({...payload,requestId:crypto.randomUUID()});applyServer(value);if(message)notify(message);return value;}catch(e){syncState='ready';updateSave();notify(e.message||'Modifica non salvata. Riprova.');return null;}finally{writeBusy=false;document.body.classList.remove('saving');schedulePoll();}}
let view='scrivania',lessonType='Tutti',lessonClass='Tutte',projectFilter='Tutti',libraryFilter='Tutti',librarySearch='',memoryFilter='Tutti',lastFocus=null;
const statusMap={coda:['In coda','gray'],lavorazione:['In lavorazione','blue'],approvazione:['Da approvare','amber'],pausa:['In pausa','gray'],completato:['Approvato','green'],annullato:['Annullato','gray'],errore:['Da riprendere','amber']};
const badge=(text,color='blue')=>`<span class="badge ${color}">${esc(text)}</span>`;
const btn=(text,action,data='',cls='')=>`<button class="btn ${cls}" data-action="${action}" ${data}>${text}</button>`;
const progress=p=>`<div class="progress-line"><div class="progress" role="progressbar" aria-label="Avanzamento del progetto" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p.progress}"><i style="width:${p.progress}%"></i></div><span>${p.progress}%</span></div>`;
const pageHead=(title,description,action='')=>`<div class="page-heading"><div><span class="eyebrow">CLARA · IL TUO SPAZIO DIDATTICO</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
function artwork(kind){const base='viewBox="0 0 360 160" fill="none" aria-hidden="true"';if(kind==='river')return `<svg ${base}><rect width="360" height="160" fill="#e6f0ee"/><circle cx="277" cy="32" r="29" fill="#f4e8c8"/><path d="M0 95 82 43l88 74 56-48 134 40v51H0" fill="#d0e3da"/><path d="M176 0c-46 36 63 50 9 74S108 117 191 160" stroke="#9bc5d7" stroke-width="25"/><path d="M183 0c-45 36 59 50 9 74S118 117 198 160" stroke="#b7dce4" stroke-width="5"/><path d="m72 127 24-35 24 35z m32 0 26-43 26 43z" fill="#c6d8c0"/><path d="M268 106v26h24v-26h-24 m-5 0 17-17 17 17" stroke="#76988d" stroke-width="2"/><path d="M14 147h84M235 147h109" stroke="#a3bcaf"/></svg>`;
if(kind==='faces')return `<svg ${base}><rect width="360" height="160" fill="#ecebfa"/><circle cx="190" cy="83" r="81" fill="#e0e1f6"/><path d="M118 145V80c0-69 111-69 111 0v65" stroke="#a0a3cf" stroke-width="2"/><path d="M170 34c-18 22-19 32-8 47l-12 22 22 3v34m16-101c23 10 22 30 14 45l12 22-24 4v29" stroke="#6876b0" stroke-width="2.5"/><path d="M152 72h15m27 0h15M172 120h16" stroke="#6876b0" stroke-width="2.5"/><circle cx="89" cy="47" r="15" fill="#d6cff0"/><circle cx="271" cy="114" r="22" fill="#d3d8f1"/><path d="M278 34h26m-13-13v26M47 114h22m-11-11v22" stroke="#b1acd0"/></svg>`;
if(kind==='book')return `<svg ${base}><rect width="360" height="160" fill="#e5edfb"/><circle cx="280" cy="64" r="52" fill="#d5e3f7"/><path d="m91 44 81 15v76l-81-15V44Z" fill="#f7faff" stroke="#91add9"/><path d="m172 59 91-15v76l-91 15V59Z" fill="#fdfdff" stroke="#91add9"/><path d="m105 67 52 10m-52 5 52 10m-52 5 35 7m32-27 61-10m-61 25 61-10m-61 25 43-7" stroke="#b2c6e5" stroke-width="2"/><path d="m253 36 12 84m-32 18 42-84" stroke="#6285c3" stroke-width="3"/><path d="M53 112h16m-8-8v16" stroke="#a9bce0"/></svg>`;
if(kind==='columns')return `<svg ${base}><rect width="360" height="160" fill="#f3eddf"/><circle cx="250" cy="48" r="37" fill="#eee0bf"/><path d="m108 53 73-33 74 33H108Z" fill="#dbccac"/><path d="M111 60h140M105 135h151" stroke="#b0a184" stroke-width="4"/><path d="M124 65v65m38-65v65m38-65v65m38-65v65" stroke="#c7b89b" stroke-width="15"/><path d="M124 65v65m38-65v65m38-65v65m38-65v65" stroke="#e3d9c1" stroke-width="3"/><path d="M20 142h73m181 0h60" stroke="#d6c9b0"/></svg>`;
return `<svg ${base}><rect width="360" height="160" fill="#e8f0f7"/><path d="M85 82h190m-96 0v43M85 82V41h95m94 42V41h-94" stroke="#9db6cf" stroke-width="2"/><rect x="145" y="19" width="70" height="36" rx="9" fill="#b9cee6"/><rect x="48" y="68" width="76" height="33" rx="9" fill="#d0dfef"/><rect x="237" y="68" width="76" height="33" rx="9" fill="#d0dfef"/><rect x="142" y="115" width="76" height="32" rx="9" fill="#c3ddd9"/><circle cx="32" cy="29" r="10" fill="#d9e5f4"/></svg>`;}
function heroArt(){return `<div class="hero-portrait"><img src="assets/clara.webp" alt="Il volto di Clara" width="230" height="230"><span class="portrait-greeting">Clara, al tuo fianco <span>✧</span></span></div>`;}
function lessonCard(l){return `<button class="lesson-card" data-action="lesson" data-id="${l.id}"><div class="lesson-cover">${artwork(l.art)}<span class="cover-label">${esc(l.topic.toUpperCase())}</span></div><div class="lesson-body"><p class="meta">${esc(l.cls)} <span>·</span> ${esc(l.type)} <span>·</span> Esempio</p><h3>${esc(l.title)}</h3><div class="bottom"><span>${esc(l.sub)}</span>${icon('arrow')}</div></div></button>`;}
function projectRow(p){const [s,c]=statusMap[p.status];return `<div class="project-row"><div class="icon-tile ${p.cls==='2AT'?'purple':'teal'}">${icon(p.type==='PWA'?'book':'file')}</div><div class="grow"><div class="row-top"><h3>${esc(p.title)}</h3>${badge(s,c)}</div><p>${esc(p.cls)} · ${esc(p.type)}</p>${progress(p)}</div><button class="icon-btn" data-action="project" data-id="${esc(p.id)}" aria-label="Apri ${esc(p.title)}">${icon('arrow')}</button></div>`;}
function capabilityCards(){return `<section class="capabilities section-space" aria-labelledby="capabilitiesTitle"><div class="section-top"><h2 id="capabilitiesTitle">Ecco cosa posso fare per te</h2>${btn('Come lavoriamo insieme','guide','','small')}</div><div class="capability-grid">${[
 ['book','Costruire materiali didattici','Lezioni, dispense, verifiche e laboratori: salva classe, obiettivi e testi nel nuovo incarico.','Crea un incarico','new-project',''],
 ['folder','Conservare il filo del lavoro','Ritrova bozze e versioni, chiedi revisioni, approva il risultato e scaricalo in Markdown o HTML; stampa in PDF.','Apri i tuoi progetti','goto','data-view="progetti"'],
 ['memory','Ricordare le tue indicazioni','Annota metodo, decisioni e preferenze nelle note di progetto: accompagneranno i lavori affidati a Clara.','Aggiungi una nota','new-memory',''],
 ['calendar','Organizzare le scadenze','Inserisci e consulta gli impegni nella mia agenda privata. Puoi esportare una scadenza per il tuo calendario.','Aggiungi una scadenza','new-event','']
 ].map(([i,title,desc,label,action,data])=>`<article class="capability-card"><span class="icon-tile">${icon(i)}</span><h3>${title}</h3><p>${desc}</p>${btn(label+' '+icon('arrow'),action,data,'small')}</article>`).join('')}</div><div class="capability-how"><strong>Per iniziare:</strong> crea un incarico, indica il risultato desiderato e le fonti, poi scegli «Lavora con ChatGPT» per svilupparlo nella chat con il plugin collegato${state.agent?.enabled?' oppure «Affida a Clara» per la coda IA, controllata ogni ora.':' oppure attiva la programmazione per usare la coda IA.'} Le bozze restano da revisionare e approvare da te.</div><p class="capability-limits">Le schede scolastiche e l’orario sono esempi. Drive, GitHub, Google Calendar e gbprof.it sono da collegare. La vista vocale legge risposte predefinite con la voce del dispositivo. Per le PWA, progettazione e codice richiedono una successiva verifica e pubblicazione.</p></section>`;}
function renderDashboard(){return "";}
function renderClasses(){return `${pageHead('Le mie classi','Quattro percorsi, uno spazio in cui tenerli insieme.')}${info('Le sigle delle classi sono quelle indicate da te. Percorsi, attività e schede sono esempi; nessun dato degli studenti è presente.')}<div class="class-grid">${classes.map(c=>`<section class="class-card"><div class="class-head"><span class="class-symbol">${c.id}</span><div><h2>${c.name}</h2><p>${c.track} · demo</p></div></div><p class="focus-line">${c.focus}</p><div class="class-actions">${btn('Apri la classe '+icon('arrow'),'class',`data-id="${c.id}"`)}${btn('Lezioni','class-lessons',`data-id="${c.id}"`,'ghost')}${btn(icon('plus')+' Incarico','new-project',`data-cls="${c.id}"`,'ghost')}</div></section>`).join('')}</div>`;}
function renderLessons(){const filtered=lessons.filter(l=>(lessonType==='Tutti'||l.type===lessonType)&&(lessonClass==='Tutte'||l.cls===lessonClass));return `${pageHead('Lezioni e laboratori','Percorsi visivi, materiali e attività per la tua didattica.',btn(icon('plus')+' Progetta una lezione','new-project','','primary'))}<div class="filters" aria-label="Filtra i percorsi">${['Tutti','PWA','Laboratorio','Dispensa','Verifica'].map(t=>`<button class="filter ${lessonType===t?'active':''}" data-action="lesson-filter" data-filter="${t}" aria-pressed="${lessonType===t}">${t==='Tutti'?'Tutti i percorsi':t}</button>`).join('')}<select class="filter-select" id="lessonClass" aria-label="Filtra per classe"><option value="Tutte">Tutte le classi</option>${classes.map(c=>`<option ${lessonClass===c.id?'selected':''}>${c.id}</option>`).join('')}</select></div><div class="lesson-grid">${filtered.length?filtered.map(lessonCard).join(''):empty('Nessun percorso in questa selezione','Prova un’altra classe o un altro tipo di materiale.')}</div><p class="subtle-note">Le schede aprono brevi anteprime illustrative, non i materiali reali di gbprof.</p>`;}
function renderProjects(){const filtered=state.projects.filter(p=>projectFilter==='Tutti'||p.status===projectFilter);return `${pageHead('Progetti in corso','Dall’idea alla revisione, senza perdere il filo.',btn(icon('plus')+' Nuovo incarico','new-project','','primary'))}${info('Incarichi e risultati restano nell’archivio privato. Premi «Affida a Clara» per lo sviluppo IA programmato, oppure «Lavora con ChatGPT» per lavorare subito nella chat. Le bozze attendono sempre la tua revisione.')}<div class="filters">${[['Tutti','Tutti'],['coda','In coda'],['lavorazione','In lavorazione'],['approvazione','Da approvare'],['pausa','In pausa'],['completato','Approvati'],['annullato','Annullati'],['errore','Da riprendere']].map(([f,t])=>`<button class="filter ${projectFilter===f?'active':''}" data-action="project-filter" data-filter="${f}" aria-pressed="${projectFilter===f}">${t}</button>`).join('')}</div><div class="project-grid">${filtered.length?filtered.map(p=>`<article class="project-card"><div class="row-top">${badge(p.cls+' · '+p.type,'gray')}${badge(...statusMap[p.status])}</div><h3>${esc(p.title)}</h3><p>${esc(p.brief)}</p>${progress(p)}${btn('Apri il progetto '+icon('arrow'),'project',`data-id="${esc(p.id)}"`)}</article>`).join(''):empty('Nessun progetto in questa fase','Crea un incarico oppure cambia filtro.')}</div>`;}
function renderLibrary(){const list=resources.filter(r=>(libraryFilter==='Tutti'||state.stars.includes(r.id))&&(!librarySearch||(r.title+' '+r.kind+' '+r.cls).toLowerCase().includes(librarySearch.toLowerCase())));return `${pageHead('Biblioteca','Un luogo per ritrovare idee, materiali e fonti.')}${info('Le bozze dei tuoi progetti sono conservate qui. Le altre schede sono esempi dichiarati; Google Drive non è collegato.')}<div class="filters"><div class="search-field">${icon('search')}<input id="librarySearch" placeholder="Cerca una scheda, una classe…" value="${esc(librarySearch)}" aria-label="Cerca in biblioteca"></div>${['Tutti','Preferiti'].map(t=>`<button class="filter ${libraryFilter===t?'active':''}" data-action="library-filter" data-filter="${t}" aria-pressed="${libraryFilter===t}">${t}</button>`).join('')}</div><div id="resourceList">${resourceList(list)}</div><section class="section-space"><div class="section-top"><h2>Le bozze conservate da Clara</h2>${badge('Archivio privato','blue')}</div><div class="project-grid">${state.projects.filter(p=>p.artifacts?.length).map(p=>`<article class="project-card">${badge(...statusMap[p.status])}<h3>${esc(p.title)}</h3><p>${esc(p.cls)} · ${p.artifacts.length} versioni · ${p.artifacts[0].source==='guided'?'Traccia guidata':'Contenuto salvato'}</p>${btn('Leggi la bozza','artifact',`data-id="${esc(p.id)}"`)}</article>`).join('')||empty('Le tue bozze appariranno qui','Prepara un primo incarico nella sezione Progetti.')}</div></section>`;}
function resourceList(list){return list.length?`<div class="library-list">${list.map(r=>`<article class="resource-row"><span class="icon-tile">${icon('file')}</span><div class="grow"><h3>${esc(r.title)}</h3><p>${esc(r.cls)} · ${esc(r.kind)} · Scheda dimostrativa</p></div><button class="icon-btn ${state.stars.includes(r.id)?'starred':''}" data-action="star" data-id="${r.id}" aria-label="${state.stars.includes(r.id)?'Rimuovi dai':'Aggiungi ai'} preferiti: ${esc(r.title)}" aria-pressed="${state.stars.includes(r.id)}">${icon('star')}</button>${btn('Apri','resource',`data-id="${r.id}"`,'small')}</article>`).join('')}</div>`:empty('Nessun risultato','Prova un termine diverso oppure visualizza tutta la raccolta.');}
function renderCalendar(){const slots=[['1I','4I','2AT',null,'1I'],['4I','2AT',null,'1I','4I'],[null,'1I','4I','2AT',null],['2AT',null,'1I','4I','2E'],[null,'2E','2AT',null,'4I']];const hours=['08:10','09:00','09:50','11:00','11:50'];return `${pageHead('Scuola e calendario','Una settimana leggibile, scadenze a portata di sguardo.',btn(icon('plus')+' Nuova scadenza','new-event','','primary'))}${info('L’orario qui sotto è completamente inventato. Non è il tuo calendario ufficiale. Le sigle in rosso mostrano come apparirà l’indicazione «con presenza».')}<div class="section-top"><h2>La settimana · esempio</h2>${badge('Orario non ufficiale','amber')}</div><div class="week-wrap"><table class="week"><thead><tr><th scope="col">ORA</th>${['LUNEDÌ','MARTEDÌ','MERCOLEDÌ','GIOVEDÌ','VENERDÌ'].map(d=>`<th scope="col">${d}</th>`).join('')}</tr></thead><tbody>${slots.map((row,i)=>`<tr><th scope="row" class="time-label">${hours[i]}</th>${row.map((c,j)=>`<td>${c?`<span class="calendar-slot ${c==='2E'?'presence':c==='2AT'?'teal':''}"><strong>${c}</strong>${c==='2E'?'Con presenza':(i+j)%2?'Italiano':'Storia'}</span>`:''}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="legend"><span><span class="legend-dot"></span>Attività dimostrativa</span><span><span class="legend-dot red"></span>Con presenza · esempio</span><span>Durata e distribuzione inventate</span></div><section class="section-space"><div class="section-top"><h2>Scadenze da tenere a mente</h2>${badge('Agenda privata','gray')}</div><div class="event-list">${state.events.length?state.events.slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(e=>{const d=new Date(e.date+'T12:00:00');return `<div class="event-row"><span class="event-day"><strong>${d.getDate()}</strong><span>${d.toLocaleDateString('it-IT',{month:'short'})}</span></span><div class="grow"><h3>${esc(e.title)}</h3><p>${esc(e.date.split('-').reverse().join('/'))} · ${esc(e.time)} · ${esc(e.cls)} · Agenda di Clara</p></div>${btn('Dettagli','event',`data-id="${esc(e.id)}"`,'small')}</div>`;}).join(''):empty('Nessuna scadenza','Aggiungi un esempio per provare l’agenda.')}</div></section>`;}
function renderMemory(){const list=state.memories.filter(m=>memoryFilter==='Tutti'||m.kind===memoryFilter);return `${pageHead('Note di progetto','Decisioni, istruzioni e il filo delle tue scelte.',btn(icon('plus')+' Aggiungi una nota','new-memory','','primary'))}${info('Queste note sono conservate nell’archivio privato di Clara e disponibili quando riapri l’app con il tuo account. ChatGPT può leggerle attraverso il plugin; non modificano la sua memoria generale.')}<div class="memory-grid"><section class="panel"><div class="section-top"><h2>Ciò che vogliamo ricordare</h2></div><div class="filters">${['Tutti','Metodo','Istruzione','Decisione'].map(t=>`<button class="filter ${memoryFilter===t?'active':''}" data-action="memory-filter" data-filter="${t}" aria-pressed="${memoryFilter===t}">${t}</button>`).join('')}</div>${list.length?list.map(m=>`<article class="memory-item"><div class="row-top">${badge(m.kind,'blue')}<button class="text-btn" data-action="edit-memory" data-id="${esc(m.id)}">Modifica</button></div><h3>${esc(m.text)}</h3><p class="subtle-note">${esc(m.at)} · Archivio di Clara</p></article>`).join(''):empty('Nessuna nota in questa categoria','Puoi aggiungere una nota o cambiare filtro.')}</section><section class="panel"><div class="section-top"><h2>Il filo del lavoro</h2>${badge('Cronologia','gray')}</div><ul class="timeline">${state.history.slice(0,15).map(h=>`<li><h3>${esc(h.text)}</h3><p>${esc(h.at)}</p></li>`).join('')}</ul></section></div>`;}
const info=text=>`<div class="info-box">${icon('help')}<p>${text}</p></div>`;
const empty=(t,d)=>`<div class="empty"><h3>${t}</h3><p class="smalltext">${d}</p></div>`;
function route(){const target=location.hash.slice(1).split('?')[0]||'scrivania';view=navs.some(n=>n[0]===target)?target:'scrivania';render();setMenu(false);}
function render(){document.body.classList.toggle('home-mode',view==='scrivania');const n=navs.find(n=>n[0]===view);$('#crumb').textContent=n[1];document.title=n[1]+' — Clara';$('#navigation').innerHTML=navs.map(([id,label,i])=>`<a class="nav-item ${id===view?'active':''}" href="#${id}" ${id===view?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='progetti'?`<span class="count">${state.projects.filter(p=>!['completato','annullato'].includes(p.status)).length}</span>`:''}</a>`).join('');$('#main').innerHTML=({scrivania:renderDashboard,classi:renderClasses,lezioni:renderLessons,progetti:renderProjects,biblioteca:renderLibrary,calendario:renderCalendar,memoria:renderMemory}[view])();updateSave();}
function goto(v){if(location.hash==='#'+v){view=v;render();}else location.hash=v;window.scrollTo({top:0,behavior:'instant'});}
function notify(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').hidden=true,5000);}
function setMenu(open){$('#sidebar').classList.toggle('open',open);$('#scrim').hidden=!open;$('#menuToggle').setAttribute('aria-expanded',String(open));}
function openModal(title,html,eyebrow='CLARA · SPAZIO PRIVATO'){openProjectId=null;lastFocus=document.activeElement;$('#modalTitle').textContent=title;$('#modalEyebrow').textContent=eyebrow;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){openProjectId=null;$('#modal').close();}
function showNewProject(cls='1I',title='',brief='',editId=''){const old=state.projects.find(p=>p.id===editId);if(old){cls=old.cls;title=old.title;brief=old.brief;}openModal(old?'Modifica l’incarico':'Un’idea diventa un incarico',`<form id="projectForm" data-id="${esc(editId)}"><label class="field">Titolo dell’incarico<input name="title" required maxlength="120" placeholder="Es. Una lezione visuale sul Rinascimento" value="${esc(title)}"></label><div class="form-grid"><label class="field">Classe<select name="cls">${classes.map(c=>`<option ${c.id===cls?'selected':''}>${c.id}</option>`).join('')}</select></label><label class="field">Risultato desiderato<select name="type">${['Lezione','PWA','Laboratorio','Dispensa','Verifica'].map(t=>`<option ${old?.type===t?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="field mt">Che cosa vuoi costruire?<textarea name="brief" required maxlength="12000" placeholder="Descrivi il percorso, gli obiettivi e i materiali da preparare…">${esc(brief)}</textarea></label><p class="modal-note">Incarico salvato sul server privato di Clara. Potrai affidarlo all’esecutore IA programmato, lavorare con ChatGPT o preparare una traccia guidata. Nessun servizio didattico esterno è collegato.</p><div class="form-actions">${btn('Annulla','close')}<button class="btn primary" type="submit">${icon('check')} ${old?'Salva le modifiche':'Crea l’incarico'}</button></div></form>`);}
function showProject(id){const p=state.projects.find(p=>p.id===id);if(!p)return;const stale=p.status==='lavorazione'&&p.engine==='guided'&&Date.now()-Date.parse(p.runStartedAt)>35000;const data=`data-id="${esc(id)}"`;let controls='';if(p.status==='approvazione')controls=btn(icon('check')+' Approva la bozza','approve',data,'primary')+btn('Richiedi revisione','revision-form',data);else if(p.status==='completato')controls=badge('Bozza approvata in Clara','green')+btn('Nuova revisione','revision-form',data);else if(p.status==='lavorazione'&&!stale)controls=btn(icon('pause')+' Metti in pausa','pause',data);else if(p.status!=='annullato'){if(p.background&&p.status==='coda')controls=badge('Affidato · prossimo controllo entro un’ora','blue')+btn('Metti in pausa','pause',data);else if(p.background&&p.status==='pausa')controls=btn(icon('play')+' Riprendi il lavoro IA','resume',data,'primary');else{if(state.agent?.enabled)controls=btn(icon('spark')+' Affida a Clara','enqueue',data,'primary');controls+=btn('Lavora con ChatGPT','chat-project',data);controls+=btn(icon('play')+(stale?' Riprendi la traccia guidata':' Prepara una traccia guidata'),stale?'resume':'run',data,'small');}}if(['approvazione','completato'].includes(p.status))controls+=btn('Lavora con ChatGPT','chat-project',data);openModal(p.title,`<div class="row-top">${badge(p.cls+' · '+p.type,'gray')}${badge(...statusMap[p.status])}</div><p class="project-detail-desc">${esc(p.brief)}</p>${progress(p)}<p class="project-stage">${icon('clock')} ${esc(p.stage||'Incarico salvato')}</p>${p.background&&p.leaseUntil&&p.status==='lavorazione'?'<p class="subtle-note">Il risultato parziale viene conservato durante il lavoro. Se l’esecuzione si interrompe, un controllo successivo lo riprende.</p>':''}${p.revisionNotes?.length?`<div class="revision-box"><strong>Revisione richiesta</strong><p>${esc(p.revisionNotes.at(-1).text)}</p></div>`:''}<div class="inline-actions mt">${controls}</div>${p.artifacts?.length?`<div class="deliverable-card"><span class="icon-tile">${icon('file')}</span><div class="grow"><h3>${esc(p.artifacts[0].title)}</h3><p>${p.artifacts[0].source==='guided'?'Traccia da modello didattico · senza IA':p.artifacts[0].source==='scheduled'?'Bozza dell’esecutore IA':'Bozza conservata'} · ${p.artifacts.length} versioni</p></div>${btn('Leggi e scarica','artifact',data,'primary small')}</div>`:''}${p.checkpoint?`<details class="checkpoint"><summary>Ultimo checkpoint conservato</summary><pre>${esc(p.checkpoint)}</pre></details>`:''}${p.checkpoints?.length?`<details class="checkpoint"><summary>Risultati parziali · ${p.checkpoints.length}</summary>${p.checkpoints.map(c=>`<h3>${esc(c.stage)}</h3><pre>${esc(c.content)}</pre>`).join('')}</details>`:''}<p class="modal-note">L’esecutore controlla la coda ogni ora; non lavora continuamente. Le tracce guidate sono schemi senza IA. L’approvazione conserva il risultato in Clara.</p><div class="inline-actions">${!['lavorazione','annullato'].includes(p.status)?btn('Modifica incarico','edit-project',data,'small'):''}${!['annullato','completato'].includes(p.status)?btn('Annulla incarico','cancel-project',data,'small'):''}</div><div class="section-top mt"><h3>Cronologia del progetto</h3></div><ul class="timeline">${p.log.slice().reverse().map(h=>`<li><h3>${esc(h.text)}</h3><p>${esc(h.at)}</p></li>`).join('')}</ul>`);openProjectId=id;}

async function updateProject(id,action){const result=await dispatch({op:action,projectId:id},action==='approve'?'Bozza approvata in Clara.':action==='enqueue'?'Lavoro affidato: Clara lo prenderà in carico al prossimo controllo.':action==='run'||action==='resume'?'Esecuzione richiesta e stato salvato.':'Stato del progetto aggiornato.');if(result)showProject(id);}
function showLesson(id){const l=lessons.find(l=>l.id===id);if(!l)return;openModal(l.title,`<div class="lesson-cover" style="height:160px;border-radius:12px">${artwork(l.art)}<span class="cover-label">ANTEPRIMA DIMOSTRATIVA</span></div><div class="inline-actions mt">${badge(l.cls)}${badge(l.type,'purple')}${badge('Contenuto di esempio','gray')}</div><div class="preview-text"><h3>La domanda da cui partire</h3><p>${esc(l.question)}</p><h3>Un percorso possibile</h3><ul>${l.outline.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Il punto di arrivo</h3><p>Costruire una spiegazione personale, motivarla con esempi e riconoscere le domande che restano aperte.</p></div><div class="form-actions">${btn('Crea un incarico da questa idea '+icon('arrow'),'lesson-project',`data-id="${l.id}"`,'primary')}</div><p class="modal-note">Anteprima breve scritta per il prototipo. Nessuna PWA, dispensa o verifica reale viene aperta o modificata.</p>`);}
function showClass(id){const c=classes.find(c=>c.id===id);if(!c)return;openModal(c.name+' · '+c.id,`<p class="smalltext muted">Scheda dimostrativa. Nessun registro, elenco studenti o dato personale.</p><div class="section-top mt"><h3>Il percorso della classe</h3>${badge('Esempio','gray')}</div><p class="smalltext muted">${esc(c.focus)}</p><div class="section-top mt"><h3>Lezioni da esplorare</h3></div><div class="lesson-grid">${lessons.filter(l=>l.cls===id).map(lessonCard).join('')}</div><div class="section-top mt"><h3>Progetti della classe</h3></div>${state.projects.filter(p=>p.cls===id).map(projectRow).join('')||'<p class="smalltext muted">Nessun progetto dimostrativo per questa classe.</p>'}<div class="form-actions">${btn(icon('plus')+' Un nuovo incarico per '+id,'new-project',`data-cls="${id}"`,'primary')}</div>`);}
function showResource(id){const r=resources.find(r=>r.id===id);if(!r)return;openModal(r.title,`${badge(r.kind,'purple')} ${badge(r.cls,'gray')}<div class="preview-text"><h3>Una scheda di esempio</h3><p>${esc(r.desc)}</p><h3>Appunti da cui partire</h3><ul><li>Quale domanda apre il percorso?</li><li>Quali materiali permettono di osservare e confrontare?</li><li>Che cosa deve saper spiegare lo studente?</li></ul></div><p class="modal-note">Questa scheda non corrisponde a un file di Drive. Nell’app definitiva qui troverai la fonte e il documento originale.</p><div class="form-actions">${btn(icon('star')+(state.stars.includes(id)?' Rimuovi dai preferiti':' Aggiungi ai preferiti'),'star',`data-id="${id}"`)}</div>`);}
function showMemory(id){const m=state.memories.find(m=>m.id===id);openModal(m?'Modifica una nota':'Una nota da conservare',`<form id="memoryForm" data-id="${esc(id||'')}"><label class="field">Tipo di nota<select name="kind">${['Metodo','Istruzione','Decisione'].map(k=>`<option ${m?.kind===k?'selected':''}>${k}</option>`).join('')}</select></label><label class="field">Che cosa vuoi ricordare?<textarea name="text" required maxlength="1500">${esc(m?.text||'')}</textarea></label>${m?btn('Rimuovi nota','delete-memory',`data-id="${esc(id)}"`,'small'):''}<p class="modal-note">La nota è salvata nell’archivio privato di Clara. Non aggiorna la memoria generale di ChatGPT.</p><div class="form-actions">${btn('Annulla','close')}<button type="submit" class="btn primary">${icon('check')} Salva la nota</button></div></form>`);}
function showNewEvent(id=''){const old=state.events.find(e=>e.id===id),today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome'}).format(new Date());openModal(old?'Modifica la scadenza':'Una scadenza nell’agenda di Clara',`<form id="eventForm" data-id="${esc(id)}"><label class="field">Titolo<input name="title" required maxlength="120" value="${esc(old?.title||'')}" placeholder="Es. Revisione di una lezione"></label><div class="form-grid"><label class="field">Data<input type="date" name="date" required value="${esc(old?.date||today)}"></label><label class="field">Ora · Europe/Rome<input type="time" name="time" required value="${esc(old?.time||'15:30')}"></label></div><label class="field mt">Classe<select name="cls">${['Tutte',...classes.map(c=>c.id)].map(c=>`<option ${old?.cls===c?'selected':''}>${c}</option>`).join('')}</select></label><p class="modal-note">Salvata nell’archivio di Clara. Non crea eventi in Google Calendar e non invia promemoria. Puoi scaricare un file calendario da importare personalmente.</p><div class="form-actions">${btn('Annulla','close')}<button class="btn primary" type="submit">Salva la scadenza</button></div></form>`);}
function showEvent(id){const e=state.events.find(e=>e.id===id);if(!e)return;openModal(e.title,`${badge('Agenda di Clara','blue')}<p class="project-detail-desc">${esc(e.date.split('-').reverse().join('/'))} · ${esc(e.time)} (Europe/Rome)<br>Classe: ${esc(e.cls)}</p><p class="modal-note">Nessun promemoria è attivo e Google Calendar non è collegato.</p><div class="form-actions">${btn('Modifica','edit-event',`data-id="${esc(id)}"`)}${btn(icon('download')+' Scarica calendario','export-event',`data-id="${esc(id)}"`)}${btn('Rimuovi','delete-event',`data-id="${esc(id)}"`,'danger')}</div>`);}
function showIntegrations(){openModal('Uno spazio connesso, passo dopo passo',`<p class="smalltext muted">Il sito non eredita le connessioni dell’account. Nella conversazione ChatGPT può usare GitHub, Drive e gli altri strumenti solo se disponibili e autorizzati. Questa finestra non ne verifica lo stato.</p><div class="connection-grid mt">${[['GD','Google Drive','Materiali, fonti e documenti. Collegamento da autorizzare.'],['GH','GitHub','Repository e revisioni. Lettura e scrittura da configurare separatamente.'],['31','Google Calendar','Orario e scadenze. Account e calendario da selezionare.'],['gb','gbprof.it','Collegamenti alle lezioni e pubblicazione dopo revisione.']].map(([logo,t,d])=>`<section class="connection-card"><div class="row-top"><span class="connection-logo">${logo}</span>${icon('link')}</div><h3>${t}</h3><p>${d}</p>${badge('Nessun collegamento diretto dal sito','gray')}</section>`).join('')}</div><p class="modal-note">Nessuna integrazione didattica viene attivata da questa finestra. Nessun file su GitHub, Drive o gbprof.it è stato modificato.</p><div class="form-actions">${btn('Funzioni e prossima fase','guide','','primary')}</div>`,'CLARA · CONNESSIONI PREVISTE');}
function agentStatus(){const a=state.agent||{};return `<section class="panel section-space"><div class="section-top"><h2>Clara al lavoro</h2>${badge(a.enabled?'Esecuzione programmata attiva':'Esecuzione programmata da attivare',a.enabled?'green':'gray')}</div><p class="smalltext muted">${a.enabled?'Controllo della coda ogni ora · Europe/Rome. Lavora su un incarico per esecuzione; per progetti estesi conserva checkpoint e prosegue nei controlli successivi.':'Puoi già conservare incarichi, note, scadenze e lavorare nella chat dopo il collegamento del plugin.'}</p><p class="subtle-note">Ultimo controllo: ${a.lastCheckedAt?esc(new Date(a.lastCheckedAt).toLocaleString('it-IT',{timeZone:'Europe/Rome'})):'nessuna esecuzione registrata'}. ${esc(a.lastOutcome||'')}</p></section>`;}
function showGuide(){openModal('Usare Clara ogni giorno',`<p class="smalltext muted">Incarichi, bozze, note e scadenze sono tuoi dati reali nell’archivio privato. Le schede di esempio delle classi e l’orario inventato restano segnalati.</p><ol class="guide-list"><li><span class="step-num">1</span><div><strong>Crea un incarico in Progetti.</strong><br>Indica classe, formato, obiettivi e fonti/testi necessari.</div></li><li><span class="step-num">2</span><div><strong>Scegli «Affida a Clara».</strong><br>Puoi chiudere ChatGPT: la coda viene controllata ogni ora. «Lavora con ChatGPT» serve per lo sviluppo immediato nella chat con il plugin collegato.</div></li><li><span class="step-num">3</span><div><strong>Leggi, modifica e scarica la bozza.</strong><br>Controlla contenuti e fonti; richiedi una revisione oppure approva il risultato.</div></li><li><span class="step-num">4</span><div><strong>Conserva le decisioni nelle Note di progetto.</strong><br>Le istruzioni accompagnano i nuovi lavori. L’agenda privata conserva le scadenze inserite da te.</div></li></ol>${agentStatus()}<table class="status-table"><thead><tr><th>Funzione</th><th>Stato</th></tr></thead><tbody><tr><td>Incarichi, note, scadenze, versioni e risultati</td><td>Archivio privato sul server</td></tr><tr><td>Revisione, approvazione ed esportazione</td><td>Operative dentro Clara</td></tr><tr><td>Lavoro a ChatGPT chiuso</td><td>${state.agent?.enabled?'Coda IA · controllo ogni ora':'Programmazione da attivare'}</td></tr><tr><td>Preparazione rapida di schemi</td><td>Tracce guidate · senza IA</td></tr><tr><td>Sidebar e fullscreen in ChatGPT</td><td>Extension disponibile dopo Installazione/Collegamento</td></tr><tr><td>Conversazione e microfono</td><td>Messaggi alla chat; dettatura se disponibile. Risposte e Voice nella conversazione ChatGPT</td></tr><tr><td>Drive, GitHub, Calendar, gbprof.it</td><td>Nella chat solo se disponibili e autorizzati; nessun collegamento diretto dal sito</td></tr><tr><td>PWA prodotte dall’agente</td><td>Progettazione/codice; pubblicazione e prova separate</td></tr></tbody></table><div class="guide-buttons">${btn(icon('link')+' Connessioni','integrations')}${btn(icon('download')+' Esporta archivio','export')}${btn('Riconnetti archivio','sync')}</div><div class="reset-zone"><p>Eliminazione completa: rimuove incarichi, bozze, note e scadenze.<br>Esporta prima una copia se vuoi conservarli.</p>${btn('Svuota archivio','reset-confirm','','small')}</div>`,'CLARA · GUIDA ALL’USO');}

function showSearch(){openModal('Trova il filo di un’idea',`<div class="search-field">${icon('search')}<input id="globalSearch" placeholder="Cerca una classe, una lezione, un progetto…" aria-label="Cerca in Clara"></div><div class="search-results" id="searchResults"></div>`);renderSearch('');setTimeout(()=>$('#globalSearch')?.focus(),50);}
function renderSearch(q){const needle=q.toLowerCase();const data=[...classes.map(c=>({title:c.id+' · '+c.name,sub:'Classe · Demo',action:'class',id:c.id})),...lessons.map(l=>({title:l.title,sub:l.cls+' · '+l.type+' · Esempio',action:'lesson',id:l.id})),...state.projects.map(p=>({title:p.title,sub:p.cls+' · Progetto di Clara',action:'project',id:p.id})),...resources.map(r=>({title:r.title,sub:'Biblioteca · Scheda demo',action:'resource',id:r.id})),...state.memories.map(m=>({title:m.text,sub:'Memoria · '+m.kind,action:'memory-search',id:m.id}))].filter(x=>(x.title+' '+x.sub).toLowerCase().includes(needle));$('#searchResults').innerHTML=data.length?data.slice(0,15).map(x=>`<button class="result-item" data-action="${x.action}" data-id="${esc(x.id)}"><div><strong>${esc(x.title)}</strong><span>${esc(x.sub)}</span></div>${icon('arrow')}</button>`).join(''):empty('Nessun risultato','Prova una parola diversa.');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
if(a==='close')closeModal();else if(a==='goto'){closeModal();goto(b.dataset.view);}else if(a==='guide')showGuide();else if(a==='integrations')showIntegrations();else if(a==='search')showSearch();else if(a==='sync'){syncState='loading';updateSave();await reloadState();}else if(a==='new-project')showNewProject(b.dataset.cls);else if(a==='edit-project')showNewProject('1I','','',id);else if(a==='project')showProject(id);else if(['enqueue','run','pause','resume','approve'].includes(a))await updateProject(id,a);else if(a==='cancel-project')await updateProject(id,'cancel');else if(a==='revision-form')showRevision(id);else if(a==='artifact')showArtifact(id);else if(a==='artifact-version')showArtifact(id,b.dataset.version);else if(a==='edit-artifact')editArtifact(id);else if(a==='download-md'||a==='download-html')downloadArtifact(id,b.dataset.version,a==='download-html');else if(a==='print-artifact')printArtifact(id,b.dataset.version);else if(a==='chat-project')showChatProject(id);else if(a==='send-chat'){try{await ClaraTransport.message(chatPrompt(state.projects.find(p=>p.id===id)));notify('Incarico inviato alla conversazione di ChatGPT.');}catch(error){notify(error.message);}}else if(a==='copy-prompt'){try{await navigator.clipboard.writeText(chatPrompt(state.projects.find(p=>p.id===id)));notify('Consegna copiata. Incollala nella chat con il plugin Clara selezionato.');}catch{notify('Seleziona e copia la consegna nel riquadro.');}}else if(a==='lesson')showLesson(id);else if(a==='lesson-project'){const l=lessons.find(x=>x.id===id);if(l)showNewProject(l.cls,'Sviluppare: '+l.title,l.question);}else if(a==='class')showClass(id);else if(a==='class-lessons'){closeModal();lessonClass=id;lessonType='Tutti';goto('lezioni');}else if(a==='lesson-filter'){lessonType=b.dataset.filter;render();}else if(a==='project-filter'){projectFilter=b.dataset.filter;render();}else if(a==='library-filter'){libraryFilter=b.dataset.filter;render();}else if(a==='resource')showResource(id);else if(a==='star'){if(await dispatch({op:'star',resourceId:id},'Preferiti aggiornati.'))showResource(id);}else if(a==='memory-filter'){memoryFilter=b.dataset.filter;render();}else if(a==='new-memory')showMemory();else if(a==='edit-memory'||a==='memory-search')showMemory(id);else if(a==='delete-memory'){if(await dispatch({op:'delete_memory',memoryId:id},'Nota rimossa.')){closeModal();render();}}else if(a==='new-event')showNewEvent();else if(a==='edit-event')showNewEvent(id);else if(a==='event')showEvent(id);else if(a==='delete-event'){if(await dispatch({op:'delete_event',eventId:id},'Scadenza rimossa.'))closeModal();}else if(a==='export-event')exportEvent(id);else if(a==='export')downloadFile('clara-archivio.json',JSON.stringify({description:'Archivio privato di Clara. Nessun servizio didattico esterno collegato.',exportedAt:new Date().toISOString(),data:state},null,2),'application/json');else if(a==='reset-confirm')openModal('Svuotare l’archivio privato?',`<p class="smalltext muted">Verranno eliminati tutti gli incarichi, le bozze, le note e le scadenze conservati sul server di Clara. Prima puoi esportare una copia. Questa operazione non riguarda Drive, GitHub o gbprof.it.</p><div class="form-actions">${btn('Annulla','guide')}${btn('Esporta prima una copia','export')}${btn('Elimina tutto l’archivio','reset','','danger')}</div>`);else if(a==='reset'){if(await dispatch({op:'reset',confirm:'RESET_CLARA'},'Archivio privato svuotato.')){closeModal();goto('scrivania');}}
});
document.addEventListener('submit',async e=>{if(!['projectForm','memoryForm','eventForm','revisionForm','artifactForm'].includes(e.target.id))return;e.preventDefault();const f=e.target,d=new FormData(f),v=k=>String(d.get(k)||'').trim();let payload;if(f.id==='projectForm')payload={op:f.dataset.id?'edit_project':'create_project',...(f.dataset.id?{projectId:f.dataset.id}:{}),title:v('title'),brief:v('brief'),cls:v('cls'),type:v('type')};else if(f.id==='memoryForm')payload={op:'save_memory',memoryId:f.dataset.id||undefined,text:v('text'),kind:v('kind')};else if(f.id==='eventForm')payload={op:'save_event',eventId:f.dataset.id||undefined,title:v('title'),date:v('date'),time:v('time'),cls:v('cls')};else if(f.id==='revisionForm')payload={op:'revise',projectId:f.dataset.id,note:v('note')};else payload={op:'save_artifact',projectId:f.dataset.id,title:v('title'),content:v('content')};const result=await dispatch(payload,'Salvato nell’archivio di Clara.');if(!result)return;closeModal();if(f.id==='projectForm'||f.id==='revisionForm'||f.id==='artifactForm'){projectFilter='Tutti';goto('progetti');showProject(result.projectId||f.dataset.id);}else if(f.id==='memoryForm'){memoryFilter='Tutti';goto('memoria');}else goto('calendario');});
document.addEventListener('change',e=>{if(e.target.id==='lessonClass'){lessonClass=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='globalSearch')renderSearch(e.target.value);if(e.target.id==='librarySearch'){librarySearch=e.target.value;const list=resources.filter(r=>(libraryFilter==='Tutti'||state.stars.includes(r.id))&&(r.title+' '+r.kind+' '+r.cls).toLowerCase().includes(librarySearch.toLowerCase()));$('#resourceList').innerHTML=resourceList(list);}});
$('#menuToggle').addEventListener('click',()=>setMenu(!$('#sidebar').classList.contains('open')));$('#scrim').addEventListener('click',()=>setMenu(false));document.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false);});$('#modal').addEventListener('click',e=>{const r=$('#modal').getBoundingClientRect();if(e.target===$('#modal')&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))closeModal();});$('#modal').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});window.addEventListener('hashchange',()=>{closeModal();route();});window.addEventListener('clara:state',e=>{if(!writeBusy)applyServer(e.detail);});window.addEventListener('clara:project',e=>{if(revision)showProject(e.detail);});document.addEventListener('visibilitychange',()=>{if(!document.hidden)reloadState();});window.addEventListener('pagehide',()=>clearTimeout(pollTimer));document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));route();

$('#main').innerHTML='<section class="loading-panel"><span class="loading-dot"></span><h2>Ritroviamo il filo del tuo lavoro…</h2><p>Caricamento dell’archivio privato di Clara.</p></section>';reloadState();
function markdown(content){const lines=String(content).replace(/\r/g,'').split('\n');let out='',list=false,code=false;for(const line of lines){if(line.startsWith('```')){if(list){out+='</ul>';list=false;}out+=code?'</code></pre>':'<pre><code>';code=!code;continue;}if(code){out+=esc(line)+'\n';continue;}const item=/^(?:- |\d+\. )(.*)$/.exec(line);if(item){if(!list){out+='<ul>';list=true;}out+='<li>'+esc(item[1])+'</li>';continue;}if(list){out+='</ul>';list=false;}const heading=/^(#{1,4})\s+(.*)$/.exec(line);if(heading){const n=Math.min(4,heading[1].length+1);out+=`<h${n}>${esc(heading[2])}</h${n}>`;}else if(line.startsWith('> '))out+='<blockquote>'+esc(line.slice(2))+'</blockquote>';else if(line.trim())out+='<p>'+esc(line)+'</p>';}if(list)out+='</ul>';if(code)out+='</code></pre>';return out;}
function artifactOf(id,version){const p=state.projects.find(p=>p.id===id);return {p,a:p?.artifacts?.find(a=>a.id===version)||p?.artifacts?.[0]};}
function showArtifact(id,version){const {p,a}=artifactOf(id,version);if(!a)return;const data=`data-id="${esc(id)}" data-version="${esc(a.id)}"`;openModal(a.title,`<div class="row-top">${badge(a.source==='guided'?'Traccia guidata · senza IA':a.source==='chatgpt'?'Bozza prodotta con ChatGPT':a.source==='scheduled'?'Bozza IA · esecuzione programmata':'Bozza modificata dal docente','blue')}${badge(...statusMap[p.status])}</div><p class="subtle-note">${esc(new Date(a.at).toLocaleString('it-IT',{timeZone:'Europe/Rome'}))} · ${esc(p.cls)} · ${esc(p.type)}</p><div class="inline-actions">${btn(icon('download')+' Markdown','download-md',data,'small')}${btn(icon('download')+' Scheda HTML','download-html',data,'small')}${btn('Stampa / PDF','print-artifact',data,'small')}${btn('Modifica una nuova versione','edit-artifact',`data-id="${esc(id)}"`,'small')}</div><article class="artifact-paper">${markdown(a.content)}</article><details class="checkpoint"><summary>Versioni conservate · ${p.artifacts.length}</summary><div class="version-list">${p.artifacts.map((v,i)=>btn((i===0?'Ultima bozza':'Versione '+(p.artifacts.length-i))+' · '+new Date(v.at).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'}),'artifact-version',`data-id="${esc(id)}" data-version="${esc(v.id)}"`,'small')).join('')}</div></details><div class="form-actions">${btn('Torna al progetto','project',`data-id="${esc(id)}"`,'primary')}</div>`,'CLARA · BOZZA CONSERVATA');}
function editArtifact(id){const {p,a}=artifactOf(id);if(!a)return;openModal('Rivedi la bozza',`<form id="artifactForm" data-id="${esc(id)}"><label class="field">Titolo della nuova versione<input name="title" value="${esc(a.title)}" required maxlength="160"></label><label class="field">Testo · Markdown<textarea name="content" class="artifact-editor" required maxlength="60000">${esc(a.content)}</textarea></label><p class="modal-note">La versione precedente resta conservata. Questa nuova bozza richiederà una nuova approvazione.</p><div class="form-actions">${btn('Annulla','artifact',`data-id="${esc(id)}"`)}<button class="btn primary" type="submit">Salva una nuova versione</button></div></form>`);}
function showRevision(id){openModal('Che cosa deve cambiare?',`<form id="revisionForm" data-id="${esc(id)}"><label class="field">Indicazioni per la revisione<textarea name="note" required maxlength="3000" placeholder="Es. Rendere più chiara la consegna; aggiungere una griglia; accorciare l’apertura…"></textarea></label><p class="modal-note">Le indicazioni restano collegate al progetto. Se era affidato all’esecutore IA, la revisione torna nella sua coda; altrimenti scegli come svilupparla.</p><div class="form-actions">${btn('Annulla','project',`data-id="${esc(id)}"`)}<button class="btn primary" type="submit">Registra la revisione</button></div></form>`);}
function chatPrompt(p){return `Lavora nella conversazione sull’incarico salvato ${p.id}: «${p.title}», classe ${p.cls}, formato ${p.type}. Usa il plugin Clara: leggi prima clara_get_project, comprese note di progetto e revisioni. Sviluppa il contenuto richiesto con cura; se è lungo, salva risultati parziali con clara_save_checkpoint. Consegna il contenuto completo con clara_save_artifact e lascia la bozza in attesa della mia approvazione. Usa fonti connesse solo se disponibili e autorizzate. Non modificare servizi esterni senza una mia richiesta. Distingui fonti consultate, ipotesi ed esempi. Non dichiarare che la chat continuerà autonomamente quando la chiudo.`;}
function showChatProject(id){const p=state.projects.find(p=>p.id===id);if(!p)return;openModal('Sviluppa il progetto con ChatGPT',`<p class="smalltext muted">Dopo il collegamento del plugin Clara, ChatGPT può leggere questo incarico e conservare il lavoro nella scrivania. Qui l’IA lavora nella conversazione. Per l’esecuzione a ChatGPT chiuso usa «Affida a Clara» nel progetto.</p><label class="field mt">Consegna pronta<textarea class="chat-prompt" readonly>${esc(chatPrompt(p))}</textarea></label><div class="form-actions">${ClaraTransport.embedded?btn('Invia alla conversazione','send-chat',`data-id="${esc(id)}"`,'primary'):''}${btn('Copia la consegna','copy-prompt',`data-id="${esc(id)}"`)}${btn('Torna al progetto','project',`data-id="${esc(id)}"`)}</div><p class="modal-note">Nel sito aperto direttamente puoi copiare la consegna e incollarla in Work con il plugin Clara selezionato.</p>`);}
function downloadFile(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),20000);notify('File pronto per il download.');}
function artifactHtml(p,a){return `<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(a.title)}</title><style>body{font:17px/1.65 system-ui;color:#203049;background:#f1f5fa;margin:0}main{max-width:820px;margin:40px auto;padding:42px;background:white;border-radius:18px}h1,h2,h3{line-height:1.2;color:#234c8f}h1{font-size:34px}h2{margin-top:32px}blockquote{border-left:4px solid #527bc0;padding:15px;background:#eff4fc;margin:0}pre{white-space:pre-wrap;overflow-wrap:anywhere}footer{border-top:1px solid #dde5f0;margin-top:32px;padding-top:20px;font-size:13px}textarea{box-sizing:border-box;width:100%;min-height:150px;border:1px solid #ccd8ea;border-radius:10px;padding:14px;font:inherit}button{padding:10px 18px;border:0;background:#2458a4;color:white;border-radius:9px;cursor:pointer}@media(max-width:700px){main{margin:0;padding:24px;border-radius:0}}@media print{body{background:white}main{margin:0;padding:0;max-width:none}button{display:none}}</style></head><body><main><p>CLARA · ARCHIVIO PRIVATO · ${esc(p.cls)}</p><h1>${esc(a.title)}</h1>${markdown(a.content)}<h2>Appunti personali</h2><textarea placeholder="Annotazioni sulla scheda · temporanee in questa pagina" aria-label="Appunti personali"></textarea><p><button onclick="window.print()">Stampa o salva PDF</button></p><footer>Versione: ${esc(a.id)} · Origine: ${esc(a.source)}. Nessun servizio didattico esterno collegato. Gli appunti in questa copia non vengono inviati a Clara.</footer></main></body></html>`;}
function downloadArtifact(id,version,html){const {p,a}=artifactOf(id,version);if(!a)return;const name=p.title.toLowerCase().replace(/[^a-z0-9àèéìòù]+/g,'-').slice(0,60)||'bozza';downloadFile('clara-'+name+(html?'.html':'.md'),html?artifactHtml(p,a):a.content,html?'text/html;charset=utf-8':'text/markdown;charset=utf-8');}
function printArtifact(id,version){const {p,a}=artifactOf(id,version);if(!a)return;$('#printSheet').innerHTML='<p>CLARA · '+esc(p.cls)+'</p><h1>'+esc(a.title)+'</h1>'+markdown(a.content);window.print();}
function exportEvent(id){const e=state.events.find(e=>e.id===id);if(!e)return;const escape=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const start=e.date.replaceAll('-','')+'T'+e.time.replace(':','')+'00';const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Clara//Agenda privata//IT','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+e.id+'@clara','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART;TZID=Europe/Rome:'+start,'DURATION:PT30M','SUMMARY:'+escape(e.title),'DESCRIPTION:'+escape('Agenda privata di Clara · Classe '+e.cls+'. Importazione personale, nessun promemoria impostato.'),'END:VEVENT','END:VCALENDAR',''].join('\r\n');downloadFile('clara-scadenza.ics',content,'text/calendar;charset=utf-8');}
